INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Grundsätze (Art. 5) > Speicherbegrenzung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Fordert der Grundsatz der Speicherbegrenzung gemäß Art. 5 DSGVO, dass personenbezogene Daten nur so lange gespeichert werden, wie es für den Zweck notwendig ist?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 5 Abs. 1e verlangt begrenzte Speicherdauer"}, {"text": "Nein", "correct": false, "because": "Speicherbegrenzung ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die unbegrenzte Speicherung personenbezogener Daten mit dem Grundsatz der Speicherbegrenzung vereinbar sein?', 2, '[{"text": "Nein", "correct": true, "because": "Unbegrenzte Speicherung widerspricht Art. 5"}, {"text": "Ja", "correct": false, "because": "Begrenzung ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen personenbezogene Daten nach Art. 5 DSGVO automatisch gelöscht werden, wenn der Zweck entfällt?', 2, '[{"text": "Ja", "correct": true, "because": "Löschung ist vorgeschrieben, sobald der Zweck wegfällt"}, {"text": "Nein", "correct": false, "because": "Löschpflicht besteht"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Betroffene aufgrund der Speicherbegrenzung die Löschung ihrer Daten verlangen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 17 DSGVO gewährt das Recht auf Löschung"}, {"text": "Nein", "correct": false, "because": "Recht ist gesetzlich verankert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Speicherbegrenzung nach Art. 5 DSGVO auch dann relevant, wenn gesetzliche Aufbewahrungspflichten bestehen?', 2, '[{"text": "Ja", "correct": true, "because": "Speicherung darf nur so lange wie nötig oder gesetzlich vorgeschrieben sein"}, {"text": "Nein", "correct": false, "because": "Pflichten müssen mit Speicherbegrenzung abgeglichen werden"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was bedeutet der Grundsatz der Speicherbegrenzung gemäß Art. 5 DSGVO?', 2, '[{"text": "Daten nur so lange speichern, wie für den Zweck nötig", "correct": true, "because": "Art. 5 Abs. 1e definiert dies"}, {"text": "Daten unbegrenzt speichern", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Daten ohne Zweck speichern", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderung beschreibt die Speicherbegrenzung am besten?', 3, '[{"text": "Zeitliche Begrenzung der Datenspeicherung", "correct": true, "because": "Speicherung auf Zweckdauer beschränken"}, {"text": "Unbegrenzte Datenspeicherung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme stellt die Speicherbegrenzung am effektivsten sicher?', 2, '[{"text": "Festlegung von Löschfristen", "correct": true, "because": "Begrenzt Speicherdauer"}, {"text": "Maximale Datenerhebung", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht unterstützt den Grundsatz der Speicherbegrenzung?', 2, '[{"text": "Recht auf Löschung", "correct": true, "because": "Art. 17 DSGVO erlaubt Datenlöschung"}, {"text": "Recht auf Auskunft", "correct": false, "because": "Anderer Zweck"}, {"text": "Recht auf Datenportabilität", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei Verstoß gegen die Speicherbegrenzung?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen Art. 5 strafbar"}, {"text": "Systemausfall", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Nicht relevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt der Grundsatz der Speicherbegrenzung nach Art. 5 DSGVO?', 4, '[{"text": "Begrenzte Speicherdauer", "correct": true, "because": "Nur so lange wie nötig"}, {"text": "Löschung nach Zweckentfall", "correct": true, "because": "Daten nicht länger behalten"}, {"text": "Zweckbezogene Speicherung", "correct": true, "because": "Nur für festgelegte Zwecke"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Widerspricht DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen die Speicherbegrenzung?', 3, '[{"text": "Festlegung von Löschfristen", "correct": true, "because": "Begrenzt Speicherdauer"}, {"text": "Automatische Löschprozesse", "correct": true, "because": "Sichert Einhaltung"}, {"text": "Überprüfung der Zweckmäßigkeit", "correct": true, "because": "Stellt Notwendigkeit sicher"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten sollten gemäß Speicherbegrenzung gelöscht werden?', 4, '[{"text": "Daten ohne aktuellen Zweck", "correct": true, "because": "Nicht mehr nötig"}, {"text": "Alte Kundendaten ohne Nutzung", "correct": true, "because": "Zweck entfallen"}, {"text": "Archivierte Daten ohne Rechtsgrundlage", "correct": true, "because": "Nicht mehr rechtmäßig"}, {"text": "Aktuelle Vertragsdaten", "correct": false, "because": "Noch zweckgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen die Speicherbegrenzung haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Bis zu 20 Mio. Euro möglich"}, {"text": "Schadensersatzansprüche", "correct": true, "because": "Betroffene können klagen"}, {"text": "Verarbeitungsverbot", "correct": true, "because": "Schwere Fälle"}, {"text": "Verbesserte Performance", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien der DSGVO ergänzen die Speicherbegrenzung?', 3, '[{"text": "Zweckbindung", "correct": true, "because": "Daten nur für festgelegte Zwecke"}, {"text": "Datenminimierung", "correct": true, "because": "Nur notwendige Daten erheben"}, {"text": "Rechtmäßigkeit", "correct": true, "because": "Verarbeitung muss legal sein"}, {"text": "Unbegrenzte Nutzung", "correct": false, "because": "Widerspricht DSGVO"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Speicherbegrenzung fordert begrenzte Speicherdauer. b) Daten können unbegrenzt gespeichert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Begrenzung ja, unbegrenzt nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Daten müssen nach Zweckentfall gelöscht werden. b) Speicherbegrenzung gilt nur bei Einwilligung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Löschung ja, gilt immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Betroffene können Löschung ihrer Daten verlangen. b) Gesetzliche Aufbewahrungspflichten heben Speicherbegrenzung auf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Löschung ja, Pflichten ergänzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Verstöße gegen Speicherbegrenzung können Bußgelder nach sich ziehen. b) Löschfristen sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, Fristen nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Speicherbegrenzung schützt die Privatsphäre. b) Datenminimierung ist unabhängig davon.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Privatsphäre ja, Minimierung ergänzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

